  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "向前走",
      "role": "ACTION",
      "explanation": "Directs one forward walking action; it is not repeated or edited by any other span."
    },
    {
      "text": "4m",
      "role": "QUANTITY",
      "explanation": "Supplies the distance 4 meters for the preceding walk_forward action; positive and finite."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Chinese comma separates clauses and has no action, parameter, edit, repetition, or ordering authority by itself."
    },
    {
      "text": "之后",
      "role": "RELATION",
      "explanation": "Specifies that the following turn occurs after the preceding walk action, fixing a sequential relation rather than creating another action."
    },
    {
      "text": "左转",
      "role": "ACTION",
      "explanation": "Directs one turn action to the left; the angle is given by the following quantity."
    },
    {
      "text": "四十五度",
      "role": "QUANTITY",
      "explanation": "Supplies a 45 degree angle for the preceding left turn; left/counterclockwise is positive, so this is +45 degrees."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Chinese comma separates clauses and has no action, parameter, edit, repetition, or ordering authority by itself."
    },
    {
      "text": "最后",
      "role": "RELATION",
      "explanation": "Marks the following stop as the final action after the preceding turn; it orders the action and does not add a separate action."
    },
    {
      "text": "停下",
      "role": "ACTION",
      "explanation": "Directs one terminal stop action, which has no parameters and ends the sequence."
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "The source requests exactly three actions: walk forward, turn left, and stop. No span edits, replaces, or repeats an action."
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "\"之后\" places the left turn after the walk, and \"最后\" places the stop last, yielding exactly one order: walk_forward, turn, stop."
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "There is no correction or editing clause, so no prior action, parameter, group, or relation is changed; this dimension is inapplicable and introduces no alternative."
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "No repetition is requested: each of the three actions appears once, and \"之后\"/\"最后\" are sequence markers, not repeated-action scopes."
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "\"之后\" resolves to the completion of the preceding walk_forward action, and \"最后\" resolves to the final position after the left turn. The turn direction and angle are explicit, and stop needs no argument; no external context is required."
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "The source gives one linear temporal order: walk_forward first, then turn left, finally stop, with each step following its predecessor. No simultaneity, waiting, or unspecified timing is introduced."
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "The source explicitly resolves action count, order, and parameters; it leaves no choice, scope, ordering, or relationship unresolved."
    }
  }
